import siteConfig, { isSet } from "../data/siteConfig.js";

export default function Footer() {
  // The year is generated by JavaScript, so it never goes out of date.
  const year = new Date().getFullYear();

  return (
    <footer className="footer">
      <div className="container footer__inner">
        <p className="footer__brand">
          <span className="wordmark">
            {siteConfig.initials}
            <span className="wordmark__dot" aria-hidden="true" />
          </span>
          <span>
            © {year} {siteConfig.name}. Designed with curiosity.
          </span>
        </p>

        <ul className="footer__links">
          {isSet(siteConfig.linkedin) && (
            <li>
              <a href={siteConfig.linkedin} target="_blank" rel="noopener noreferrer">
                LinkedIn
              </a>
            </li>
          )}
          {isSet(siteConfig.github) && (
            <li>
              <a href={siteConfig.github} target="_blank" rel="noopener noreferrer">
                GitHub
              </a>
            </li>
          )}
        </ul>
      </div>
    </footer>
  );
}
